validators.Research:
const sample={"title": "", "alternate_titles": ["", "", ""], "total_duration_seconds": 0, "hook": "", "setup": "", "main_content": "", "payoff": "", "cta": "", "full_voiceover": "", "scenes": [{"scene_id": 1, "duration_seconds": 0, "script_section": "hook", "what_happens": "", "viewer_takeaway": "", "visual_concept": "", "voiceover": "", "on_screen_text": [], "dialogue": [], "sound_design": "", "transition": ""}]};
function check(value,shape,path){
 if(Array.isArray(shape)){if(!Array.isArray(value))throw new Error(path+' must be an array');if(shape.length&&value.length===0&&path.endsWith('scenes'))throw new Error(path+' must not be empty');if(shape.length)for(let i=0;i<value.length;i++)check(value[i],shape[0],path+'['+i+']');return;}
 if(shape&&typeof shape==='object'){if(!value||typeof value!=='object'||Array.isArray(value))throw new Error(path+' must be an object');for(const k of Object.keys(shape)){if(!Object.prototype.hasOwnProperty.call(value,k))throw new Error(path+'.'+k+' required; no synthesized defaults');check(value[k],shape[k],path+'.'+k);}return;}
 if(typeof value!==typeof shape||(typeof value==='number'&&!Number.isFinite(value)))throw new Error(path+' has invalid type');
}
return $input.all().map((item,index)=>{
 const start=$('Start AI Timing').item.json._aiStartedAt;
 let valid=true,error='';try{check(item.json.output,sample,'output');
 const s=item.json.output;
 if(!Array.isArray(s.scenes)||!s.scenes.length)throw new Error('Script scenes missing');
 let total=0;for(let i=0;i<s.scenes.length;i++){const c=s.scenes[i];if(c.scene_id!==i+1)throw new Error('Script scene IDs/order invalid');if(typeof c.duration_seconds!=='number'||!Number.isFinite(c.duration_seconds)||c.duration_seconds<=0)throw new Error('Script scene duration invalid');total+=c.duration_seconds;}
 if(total!==s.total_duration_seconds||total<45||total>60)throw new Error('Script duration total/45-60s invalid');
 if(s.scenes.map(c=>c.voiceover).join(' ').trim().split(/\s+/).join(' ')!==s.full_voiceover.trim().split(/\s+/).join(' '))throw new Error('full_voiceover does not match scene narration');
if(item.json.output.full_voiceover!==undefined&&!item.json.output.full_voiceover.trim())throw new Error('full_voiceover is empty');}catch(e){valid=false;error=e.message;}
 const model=item.json.response_metadata?.model||item.json.metadata?.model||item.json.model||'unknown';
 const row=$('Capture Acquired Lock').item.json;
 return {json:{...item.json,_aiMetric:{JobID:String(row.JobID??row._context.currentId),Task:String($workflow.name),Model:typeof model==='string'?model:'unknown',ExecutionID:String($execution.id),DurationMs:Math.max(0,Date.now()-start),ValidOutput:valid,Error:error}},pairedItem:{item:index}};
});

validators.Scene Production:
const sample={"project": "AI That Can Build Its Own Workflow", "format": "youtube_short", "aspect_ratio": "9:16", "scenes": [{"scene_id": "SCENE_01", "duration": "0-3", "type": "image", "scene": "...", "visual": "...", "prompt": "...", "voiceover": "...", "on_screen_text": "...", "sound": "..."}]};
function check(value,shape,path){
 if(Array.isArray(shape)){if(!Array.isArray(value))throw new Error(path+' must be an array');if(shape.length&&value.length===0&&path.endsWith('scenes'))throw new Error(path+' must not be empty');if(shape.length)for(let i=0;i<value.length;i++)check(value[i],shape[0],path+'['+i+']');return;}
 if(shape&&typeof shape==='object'){if(!value||typeof value!=='object'||Array.isArray(value))throw new Error(path+' must be an object');for(const k of Object.keys(shape)){if(!Object.prototype.hasOwnProperty.call(value,k))throw new Error(path+'.'+k+' required; no synthesized defaults');check(value[k],shape[k],path+'.'+k);}return;}
 if(typeof value!==typeof shape||(typeof value==='number'&&!Number.isFinite(value)))throw new Error(path+' has invalid type');
}
return $input.all().map((item,index)=>{
 const start=$('Start AI Timing').item.json._aiStartedAt;
 let valid=true,error='';try{check(item.json.output,sample,'output');
 const o=item.json.output;let src=$('Start AI Timing').item.json.Script;if(typeof src==='string')src=JSON.parse(src);
 if(!src||!Array.isArray(src.scenes)||!src.full_voiceover)throw new Error('Complete source script object required for coverage validation');
 if(o.format!=='youtube_short'||o.aspect_ratio!=='9:16'||o.scenes.length!==src.scenes.length)throw new Error('Full script scene/format coverage mismatch');
 let cursor=0;for(let i=0;i<o.scenes.length;i++){const c=o.scenes[i],s=src.scenes[i];if(c.scene_id!=='SCENE_'+String(i+1).padStart(2,'0'))throw new Error('Scene IDs/order invalid');if(c.voiceover!==s.voiceover)throw new Error('Source narration was changed');const m=/^\s*(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)\s*$/.exec(String(c.duration));if(!m||Number(m[1])!==cursor||Number(m[2])-Number(m[1])!==s.duration_seconds||Number(m[2])<=Number(m[1]))throw new Error('Source scene timing changed');cursor=Number(m[2]);if(!['text_to_image','image_to_video','flf_to_video'].includes(c.generation_type??c.type))throw new Error('Unsupported scene generation type');}
 if(cursor!==src.total_duration_seconds)throw new Error('Scene timing does not cover full script');
if(item.json.output.full_voiceover!==undefined&&!item.json.output.full_voiceover.trim())throw new Error('full_voiceover is empty');}catch(e){valid=false;error=e.message;}
 const model=item.json.response_metadata?.model||item.json.metadata?.model||item.json.model||'unknown';
 const row=$('Capture Acquired Lock').item.json;
 return {json:{...item.json,_aiMetric:{JobID:String(row.JobID??row._context.currentId),Task:String($workflow.name),Model:typeof model==='string'?model:'unknown',ExecutionID:String($execution.id),DurationMs:Math.max(0,Date.now()-start),ValidOutput:valid,Error:error}},pairedItem:{item:index}};
});

